    next.remainder := next_rem(D_WIDTH, 0)
    next.quotient := Cat(state.quotient(ITERATIONS - 2, 0), quotient_bit)
    next.dividend := Cat(state.dividend(N_WIDTH - 2, 0), 0.U(1.W))

